(()=>{const player=document.querySelector('#live iframe');if(!player)return;let current='EHm0EectsVA';function apply(data){const now=Date.now()/1000;const session=(data.sessions||[]).find(s=>s.start<=now&&s.end>now&&/^[A-Za-z0-9_-]{11}$/.test(s.video_id));if(session&&session.video_id!==current){current=session.video_id;player.src='https://www.youtube.com/embed/'+current+'?mute=1&playsinline=1'}}async function refresh(){try{const response=await fetch('https://data.starpeople.ai/snapshot/youtube.json',{cache:'no-store'});if(response.ok)apply(await response.json())}catch{}}fetch('live-sessions.json').then(r=>r.json()).then(apply).then(refresh).catch(refresh);setInterval(()=>{if(!document.hidden)refresh()},60000)})();
